/**
 * @param {string} s
 * @param {string} t
 * @return {string}
 */
var minWindow = function(s, t) {
    if (!s || !t || s.length < t.length) return "";

    // 步骤 1：统计目标串 t 中各字符的需求数量
    const need = new Map();
    for (const ch of t) {
        need.set(ch, (need.get(ch) || 0) + 1);
    }

    // 记录窗口内各字符的实时数量
    const window = new Map();
    let left = 0;
    let matched = 0; // 记录有多少种字符已经达到 need 要求的数量
    let minLen = Infinity;
    let startIdx = 0;

    // 步骤 2：右指针向右扩展，寻找可行解
    for (let right = 0; right < s.length; right++) {
        const c = s[right];
        window.set(c, (window.get(c) || 0) + 1);

        // 如果字符 c 是目标字符，且窗口内存量恰好达到目标需求，达标种类数加 1
        if (need.has(c) && window.get(c) === need.get(c)) {
            matched++;
        }

        // 步骤 3：当所有字符种类均已集齐，左指针极限向右收缩，寻找局部最优解
        while (matched === need.size) {
            // 刷新历史最小覆盖子串的长度与起始位置
            if (right - left + 1 < minLen) {
                minLen = right - left + 1;
                startIdx = left;
            }

            // 尝试移出左边界字符
            const leftChar = s[left];
            window.set(leftChar, window.get(leftChar) - 1);

            // 若移出的是关键字符，且移出后数量已低于需求量，则打破全满状态
            if (need.has(leftChar) && window.get(leftChar) < need.get(leftChar)) {
                matched--;
            }

            left++; // 左指针向右收缩
        }
    }

    // 步骤 4：若未找到任何合法子串返回 ""，否则返回截取的最优子串
    return minLen === Infinity ? "" : s.slice(startIdx, startIdx + minLen);
};

