/**
 * @param {number[]} nums
 * @return {number}
 */
var maxSubArray = function(nums) {
    // 步骤 1：初始账本从第一个数字起步（防全负数死穴）
    let currentSum = nums[0];
    let maxSum = nums[0];

    // 步骤 2：从第二个数字开始线性遍历
    for (let i = 1; i < nums.length; i++) {
