    const res = new Array(n).fill(1);

    // 步骤 2：第一趟——从左向右收集每个元素左侧的所有数乘积（前缀积）
    let leftProduct = 1;
    for (let i = 0; i < n; i++) {
        // 当前位置等于左边所有人累乘的结果
        res[i] = leftProduct;
        // 把当前数字乘入前缀积，留给下一个位置使用
        leftProduct *= nums[i];
    }

    // 步骤 3：第二趟——从右向左动态累乘每个元素右侧的所有数乘积（后缀积）
    let rightProduct = 1;
    for (let i = n - 1; i >= 0; i--) {
        // 现有结果（左乘积）乘以右侧所有人的乘积
        res[i] *= rightProduct;
        // 把当前数字乘入后缀积，留给前一个位置使用
        rightProduct *= nums[i];
    }

    // 步骤 4：返回构建完成的答案数组
    return res;
};

