var setZeroes = function(matrix) {
    const m = matrix.length;
    const n = matrix[0].length;

    // 第 1 步：用两个布尔哨兵分别记录第 0 行和第 0 列本身是否原本就含有 0
    let row0HasZero = false;
    let col0HasZero = false;

    // 检查第 0 行是否有 0
    for (let j = 0; j < n; j++) {
        if (matrix[0][j] === 0) {
            row0HasZero = true;
            break;
        }
    }

    // 检查第 0 列是否有 0
    for (let i = 0; i < m; i++) {
        if (matrix[i][0] === 0) {
            col0HasZero = true;
            break;
        }
    }

    // 第 2 步：借用第 0 行和第 0 列作为现成打标黑板
    // 遍历内部子矩阵 (i >= 1, j >= 1)，若当前格子为 0，则在其行首和列首打标记
    for (let i = 1; i < m; i++) {
        for (let j = 1; j < n; j++) {
            if (matrix[i][j] === 0) {
                matrix[i][0] = 0; // 标记第 i 行需要置零
                matrix[0][j] = 0; // 标记第 j 列需要置零
            }
        }
    }

    // 第 3 步：根据第 0 行和第 0 列记录的标记，将内部对应的格子置零
    for (let i = 1; i < m; i++) {
        for (let j = 1; j < n; j++) {
            if (matrix[i][0] === 0 || matrix[0][j] === 0) {
                matrix[i][j] = 0;
            }
        }
    }

    // 第 4 步：最后根据最初保存的哨兵状态，处理第 0 行自身
    if (row0HasZero) {
        for (let j = 0; j < n; j++) {
            matrix[0][j] = 0;
        }
    }

    // 第 5 步：最后根据最初保存的哨兵状态，处理第 0 列自身
    if (col0HasZero) {
        for (let i = 0; i < m; i++) {
            matrix[i][0] = 0;
        }
    }
};

