/**
 * 字典树节点类
 */
class TrieNode {
    constructor() {
        // 子字符映射表：例如 { 'a': TrieNode, 'b': TrieNode }
        this.children = {};
        // 标记是否为某个完整单词的结尾
        this.isEnd = false;
    }
}

/**
 * 初始化前缀树
 */
var Trie = function() {
    this.root = new TrieNode();
};

/** 
 * 向前缀树中插入一个单词
 * @param {string} word
 * @return {void}
 */
Trie.prototype.insert = function(word) {
    let curr = this.root;

    for (const ch of word) {
        // 若当前字符对应的分支不存在，新建节点
        if (!curr.children[ch]) {
            curr.children[ch] = new TrieNode();
        }
        // 步入子节点
        curr = curr.children[ch];
    }

    // 单词末尾节点打上完结标记
    curr.isEnd = true;
};

/**
 * 内部公共辅助函数：沿着字符串路径下探查找最终节点
 * @param {string} str
 * @return {TrieNode|null}
 */
Trie.prototype._searchNode = function(str) {
    let curr = this.root;

    for (const ch of str) {
        if (!curr.children[ch]) {
            return null; // 路径中断，不存在
        }
        curr = curr.children[ch];
    }

    return curr; // 返回路径终点节点
};

/** 
 * 检索前缀树中是否存在完整单词 word
 * @param {string} word
 * @return {boolean}
 */
Trie.prototype.search = function(word) {
    const node = this._searchNode(word);
    // 节点必须存在且打上了 isEnd 完结标记
    return node !== null && node.isEnd === true;
};

/** 
 * 检索前缀树中是否存在以 prefix 为前缀的单词
 * @param {string} prefix
 * @return {boolean}
 */
Trie.prototype.startsWith = function(prefix) {
    const node = this._searchNode(prefix);
    // 只要路径存在即代表前缀命中
    return node !== null;
};

