/**
 * @param {number[]} nums
 * @return {number[][]}
 */
var permute = function(nums) {
    const res = [];
    const path = [];
    const used = new Array(nums.length).fill(false);

    const backtrack = () => {
        // 第 1 步：终止条件——选满 n 个数字，收获一种全排列
        if (path.length === nums.length) {
            res.push([...path]); // 必须浅拷贝拍快照！
            return;
        }

        // 第 2 步：遍历所有候选数字
        for (let i = 0; i < nums.length; i++) {
            // 如果该数字已被使用过，直接跳过
            if (used[i]) continue;

            // 第 3 步：做选择
            used[i] = true;
            path.push(nums[i]);

            // 第 4 步：递归下探，继续挑选下一个位置的数字
            backtrack();

            // 第 5 步：撤销选择（回溯恢复现场）
            path.pop();
            used[i] = false;
        }
    };

    backtrack();
    return res;
};

