var generateParenthesis = function(n) {
    const res = [];
    const path = [];

    const backtrack = (left, right) => {
        // 第 1 步：放置了 2n 个括号，收集闭合串
        if (path.length === 2 * n) {
            res.push(path.join(''));
            return;
        }

        // 第 2 步：规则 1——只要左括号配额未用完，随时可放左括号
        if (left < n) {
            path.push('(');
            backtrack(left + 1, right);
            path.pop(); // 回溯
        }

        // 第 3 步：规则 2——右括号数量少于左括号时，才能放右括号闭合
        if (right < left) {
            path.push(')');
            backtrack(left, right + 1);
            path.pop(); // 回溯
        }
    };

    backtrack(0, 0);
    return res;
};

