                return True
            if r < 0 or r >= m or c < 0 or c >= n or board[r][c] != word[k]:
                return False
            temp = board[r][c]
            board[r][c] = '#'  # 标记已访问
            found = (dfs(r + 1, c, k + 1) or
                     dfs(r - 1, c, k + 1) or
                     dfs(r, c + 1, k + 1) or
                     dfs(r, c - 1, k + 1))
            board[r][c] = temp  # 回溯恢复
            return found

        for i in range(m):
            for j in range(n):
