/**
 * @param {string} s
 * @return {string[][]}
 */
var partition = function(s) {
    const res = [];
    const path = [];
    const n = s.length;

    // 双指针校验回文串辅助函数
    const isPal = (left, right) => {
        while (left < right) {
            if (s[left] !== s[right]) return false;
            left++;
            right--;
        }
        return true;
    };

    const backtrack = (start) => {
        // 第 1 步：全串被完整切分为回文段，收集方案
        if (start === n) {
            res.push([...path]);
            return;
        }

        // 第 2 步：在 [start, n - 1] 范围内枚举下刀位置 i
        for (let i = start; i < n; i++) {
            // 关键剪枝：只有当前前缀是回文才继续切
            if (isPal(start, i)) {
                // 做选择：切下 [start, i] 这一段
                path.push(s.slice(start, i + 1));

                // 第 3 步：递归切分后续剩余子串
                backtrack(i + 1);

                // 第 4 步：撤销选择（回溯）
                path.pop();
            }
        }
    };

    backtrack(0);
    return res;
};

