var solveNQueens = function(n) {
    const res = [];
    const queens = new Array(n).fill(-1); // queens[r] = c 记录每行皇后的列
    const cols = new Set();
    const diag1 = new Set(); // 记录 r - c (主对角线)
    const diag2 = new Set(); // 记录 r + c (副对角线)

    const backtrack = (r) => {
        // 第 1 步：所有 n 行都合法安放了皇后，绘制棋盘输出
        if (r === n) {
            const board = [];
            for (let i = 0; i < n; i++) {
                const c = queens[i];
                board.push('.'.repeat(c) + 'Q' + '.'.repeat(n - c - 1));
            }
            res.push(board);
            return;
        }

        // 第 2 步：尝试放在当前行 r 的每一列 c
        for (let c = 0; c < n; c++) {
            // 关键剪枝：三线冲突检测
            if (cols.has(c) || diag1.has(r - c) || diag2.has(r + c)) {
                continue;
            }

            // 第 3 步：做选择
            queens[r] = c;
            cols.add(c);
            diag1.add(r - c);
            diag2.add(r + c);

            // 第 4 步：递归安放下一行
            backtrack(r + 1);

            // 第 5 步：撤销选择（回溯）
            cols.delete(c);
            diag1.delete(r - c);
            diag2.delete(r + c);
        }
    };

    backtrack(0);
    return res;
};

