    let left = 0;
    let right = this.arr.length - 1;

    while (left <= right) {
        const mid = Math.floor((left + right) / 2);
        if (this.arr[mid] >= num) {
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }

    // 第 2 步：left 即为新数字在有序数组中的正确插入位置，将其插入保持有序
    this.arr.splice(left, 0, num);
};

