var numSquares = function(n) {
    // dp[i] 表示组成整数 i 所需的最少完全平方数个数
    // 寻找最小值，初始全部填充为正无穷大
    const dp = new Array(n + 1).fill(Infinity);
    dp[0] = 0; // 凑出 0 需要 0 个数，作为递推基石

    // 自底向上，计算每个子目标 i 的最优解
    for (let i = 1; i <= n; i++) {
        // 枚举所有不大于 i 的完全平方数 j * j
        for (let j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
};

