    // 第 0 行所有位置都只有 1 种走法（一路向右不回头），全部初始化为 1
    const dp = new Array(n).fill(1);

    // 外层循环：从第 1 行逐行推演至第 m - 1 行
    for (let i = 1; i < m; i++) {
        // 内层循环：从第 1 列推进至第 n - 1 列（第 0 列一路向下始终为 1，无需更新）
        for (let j = 1; j < n; j++) {
