/**
 * @param {number[]} nums
 * @return {number}
 */
var singleNumber = function(nums) {
    // 初始基底设为 0：因为 0 ^ x === x，不会对任何后续数字产生副作用
    let res = 0;

    // 线性遍历数组中的每一个数字进行异或消消乐
    for (const num of nums) {
        // 利用成对数字异或为 0 的特性做两两抵消
        res ^= num;
    }

    // 遍历结束，成双成对的数字全部化为 0，唯一留存的就是落单数字
    return res;
};

