/**
 * @param {number[]} nums
 * @return {number}
 */
var majorityElement = function(nums) {
    let candidate = null; // 当前擂主候选人
    let count = 0;        // 候选人当前净胜票数（兵力值）

    for (const num of nums) {
        // 当兵力耗尽归零时，说明前序子区间已同归于尽，当前数字自立为新擂主
        if (count === 0) {
            candidate = num;
        }

        // 同阵营支持票 +1，异阵营对拼抵消 -1
        count += (num === candidate ? 1 : -1);
    }

    // 题目保证多数元素必然存在（占比 > n/2），最终留存的候选人即为答案
    return candidate;
};

